{"command":"# Check actual note content in patterns
python3 -c "
import subprocess, json
def ft2(cmd, args):
    result = subprocess.run(['ft2', 'call', cmd, json.dumps(args)], capture_output=True, text=True)
    return result.stdout.strip()

# Check pattern 1 lead channel (ch0) for active notes
print('P1 Ch0 (lead) notes:')
for r in range(0, 64, 3):
    cell = json.loads(ft2('pattern_get_cell', {'pattern': 1, 'row': r, 'channel': 0}))
    txt = cell['content'][0]['text']
    d = json.loads(txt)
    if d.get('instrument', 0) > 0:
        print(f'  Row {r}: note={d[\"note_name\"]} inst={d[\"instrument\"]} vol={d[\"volume\"]}')

print()
print('P1 Ch1 (bass) notes:')
for r in range(0, 64, 3):
    cell = json.loads(ft2('pattern_get_cell', {'pattern': 1, 'row': r, 'channel': 1}))
    txt = cell['content'][0]['text']
    d = json.loads(txt)
    if d.get('instrument', 0) > 0:
        print(f'  Row {r}: note={d[\"note_name\"]} inst={d[\"instrument\"]} vol={d[\"volume\"]}')
